def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 1:
        return 'D' if history[0][1] == 'D' else 'C'

    my = [h[0] for h in history]
    op = [h[1] for h in history]

    op_c = op.count('C')
    op_d = n - op_c
    my_c = my.count('C')
    my_d = n - my_c

    # Detect always defecting opponent
    if n >= 5 and op_d >= n - 1:
        return 'D'
    if n >= 20 and op_d >= n - 2:
        return 'D'

    # If opponent has never defected
    if op_d == 0:
        if my_d == 0:
            if n < 10:
                return 'C'
            elif n == 10:
                return 'D'
            else:
                return 'D'
        else:
            first_def = my.index('D')
            if first_def + 1 < n:
                if op[first_def + 1] == 'D':
                    # They retaliated. Switch to TFT mode.
                    pass
                else:
                    return 'D'
            else:
                return 'D'

    # TFT mode
    if n == 99:
        return 'D'

    last_op = op[-1]
    last_me = my[-1]

    if n >= 95 and last_op == 'D':
        return 'D'

    if last_op == 'D':
        streak = 0
        for i in range(n - 1, -1, -1):
            if op[i] == 'D':
                streak += 1
            else:
                break
        if streak == 1:
            return 'C'
        else:
            return 'D'
    else:
        return 'C'
